import { test, expect } from '@playwright/test';

test.describe('Promo Code Validation - Expired Code', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/promo-code');
  });

  test('should display error message when entering an expired promo code', async ({ page }) => {
    // Verify promo code input field is visible
    const promoInput = page.getByLabel('Promo Code');
    await expect(promoInput).toBeVisible();

    // Verify submit button is visible
    const submitButton = page.getByRole('button', { name: /apply/i });
    await expect(submitButton).toBeVisible();

    // Enter an expired promo code
    await promoInput.fill('EXPIRED2023');

    // Click apply button
    await submitButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/This promo code has expired/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message has appropriate styling (e.g, red text)
    await expect(errorMessage).toHaveCSS('color', 'rgb(252, 12, 40)');

    // Verify promo code input field retains the value
    await expect(promoInput).toHaveValue('EXPIRED2023');

    // Verify discount field does not show a value
    const discountDisplay = page.getByText(/\$0.00/);
    await expect(discountDisplay).toBeVisible();
  });

  test('should allow user to correct and re-apply a valid promo code after expired attempt', async ({ page }) => {
    // Enter an expired promo code and submit
    const promoInput = page.getByLabel('Promo Code');
    await promoInput.fill('EXPIRED2023');
    const submitButton = page.getByRole('button', { name: /apply/i });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/This promo code has expired/i);
    await expect(errorMessage).toBeVisible();

    // Clear the expired promo code
    await promoInput.clear();

    // Enter a valid promo code
    await promoInput.fill('VALID2024');

    // Click apply button again
    await submitButton.click();

    // Verify error message is no longer visible
    await expect(errorMessage).not.toBeVisible();

    // Verify success message appears
    const successMessage = page.getByText(/Promo code applied successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify discount is applied
    const discountDisplay = page.getByText(/\$10.00/);
    await expect(discountDisplay).toBeVisible();
  });
});
